parameters.jsCode:
// The router has already done the extracting — PDF text, Vision output, several attachments
// joined and labelled. This node reads that text deterministically, in code, and hands the
// result over as settled fact.
//
// Why it is not left to the model: a quote is written in a small, closed trade vocabulary
// ("20L of 1.8H", "Disposal of 25m of old fence"), and the model read it *usually* — the same
// PDF gave five fields on one run and two on the next, and the customer got asked for a height
// they had already attached. Same document, same fields, every run.
//
// Everything here speaks the NEW schema slugs (timber_pine, pool_glass, restricted_access…),
// because those are what the businesses publish rates against.
const source = $('Normalize Input').first().json;

const extractedText = String(source.extractedText || '').slice(0, 4000);

// The router labels multiple attachments '--- Document 1 of 3 ---'. Across several documents a
// height off one quote and a total off another describe a job nobody priced, so the code reader
// stays out of it and the agent reads them instead, each one labelled.
const multipleDocuments = /^--- Document 1 of \d+ ---/m.test(extractedText);
const documents = extractedText ? [extractedText] : [];

// Heights arrive as metres, centimetres or millimetres and the three ranges barely overlap:
// under 10 was metres, 10-300 was centimetres (nothing is a 150mm fence, while a 150cm one is
// standard), above 300 is already millimetres.
const toMm = (value) =>
  value < 10 ? Math.round(value * 1000) : value <= 300 ? Math.round(value * 10) : Math.round(value);

// Longest unit spelling first, so "1.8 metres high" doesn't stop at the "m".
const UNIT = '(?:millimetres?|millimeters?|centimetres?|centimeters?|metres?|meters?|mm|cm|m)';

// Capital H and L are the trade's own suffixes ("1.8H" is a height, "20L" is a run) and are
// matched case-sensitively on purpose — a lowercase h is just the start of a word.
const HEIGHT = [
  [/(\d+(?:\.\d+)?)\s?(?:mm|m)?\s?H\b/, toMm],
  [/\bH\s?[-:]?\s?(\d{3,4})\b/, toMm],
  // Fences run 4-8ft. Ten or more feet is the length of the run, not how tall it is. Inches
  // count: 5'6" is 1676mm, and dropping them quietly shortens the fence by half a paling.
  [
    /(\d+(?:\.\d+)?)\s*(?:ft|foot|feet|')\s*(\d+)?\s*(?:"|in\b|inch(?:es)?)?/i,
    (value, match) => (value < 10 ? Math.round(value * 304.8 + (Number(match[2]) || 0) * 25.4) : null),
  ],
  [new RegExp(`(\\d+(?:\\.\\d+)?)\\s*${UNIT}?\\s*(?:high|height|tall)\\b`, 'i'), toMm],
  [/(?:height|high)\b\D{0,10}?(\d+(?:\.\d+)?)/i, toMm],
];

// "20 to 30 metres" is not an answer. The rate is charged per metre, so a span prices a job
// nobody described — better to read no length at all and let the agent ask which is closer.
const RANGE = [
  /\b\d{1,4}(?:\.\d+)?\s*(?:m\b|metres?|meters?)?\s*(?:-|–|—|to)\s*\d{1,4}(?:\.\d+)?\s*(?:m\b|lm\b|lineal|metres?|meters?)/i,
  /\bbetween\s+\d{1,4}[^\n]{0,14}?\d{1,4}\s*(?:m\b|lm\b|lineal|metres?|meters?)/i,
];

// Explicit shorthand first. The loose ones carry a 3m floor: a "1.8m" sitting on the page is
// the height, and nobody books a two metre run of fence.
const asRun = (value) => (value >= 3 ? value : null);
const LENGTH = [
  [/(\d+(?:\.\d+)?)\s*(?:lineal|linear)\s*(?:ft|foot|feet)\b/i, (value) => Math.round(value * 0.3048)],
  [/(\d+(?:\.\d+)?)\s*(?:lineal|linear)\s*(?:m\b|metres?|meters?)/i, (value) => value],
  [/(\d+(?:\.\d+)?)\s*(?:lm|l\.m\.)\b/i, (value) => value],
  [/(\d+(?:\.\d+)?)\s?L\b/, (value) => value],
  // "1800 high x 25000 long" — a supplier writing both dimensions in millimetres
  [/(\d+(?:\.\d+)?)\s*(?:mm|cm|m)?\s*(?:long|wide|in length)\b/i, (value) => value],
  [/(\d+(?:\.\d+)?)\s*m\b(?=[^\n]{0,40}?(?:fenc|run\b))/i, asRun],
  [/(\d+(?:\.\d+)?)\s*(?:odd\s+|approx\.?\s+|or so\s+)?(?:metres?|meters?)\b/i, asRun],
  // Last resort, for a line that never says the word: "post and wire 200m". The floor is what
  // makes it safe — every height on the page is under 3, in metres or otherwise.
  [/(\d+(?:\.\d+)?)\s*m\b/i, asRun],
];
// ponytail: over 500 is read as millimetres. It mis-reads a rural boundary longer than 500m;
// swap for a unit-aware capture if one ever shows up.
const asMetres = (value) => (value !== null && value > 500 ? Math.round(value / 1000) : value);

// The schema's own material slugs, specific before generic — "glass pool fence" is pool_glass,
// not timber_pine, and "merbau" is hardwood rather than the pine everyone defaults to. A
// document that only says "bamboo screening" matches nothing here on purpose: it is not a
// material anybody publishes a rate against, so the agent asks instead of guessing.
const MATERIALS = [
  ['pool_glass', /glass (?:pool )?fenc|frameless|toughened glass/i],
  ['pool_aluminium', /pool fenc|pool panel/i],
  ['colorbond', /colou?rbond/i],
  ['chainmesh', /chain ?(?:mesh|wire|link)|security fenc/i],
  ['aluminium', /alumin(?:i)?um|slat fenc|powder ?coat/i],
  ['rural_wire', /rural fenc|post and wire|farm fenc|paddock|stock fence|ringlock/i],
  ['timber_hardwood', /hardwood|merbau|spotted gum|jarrah|ironbark/i],
  ['timber_pine', /treated pine|\bpine\b|timber|paling/i],
];

// Any line about getting rid of what is already there. "Disposal of 25m of old fence" is the
// removal being quoted for, and missing it is what made the agent ask a question the document
// had already answered.
const REMOVAL = [
  /\b(?:dispos\w*|remov\w*|demoli\w*|demo|dismantl\w*|tear\s*(?:down|out)|pull\s*(?:down|out)|take\s*away|cart\s*away|strip\s*out|rip\s*out)\b[^.\n]{0,60}fenc/gi,
  // Said the other way round: "Existing 25m paling fence to be dismantled and taken to tip"
  /\b(?:old|existing|current)\b[^.\n]{0,30}?fenc\w*[^.\n]{0,40}?\b(?:remov\w*|dispos\w*|demoli\w*|dismantl\w*|pulled|taken|carted|tip)\b/gi,
];
// "no disposal of the old fence" prices a demolition nobody asked for.
const NEGATED = /\b(?:no|not|excl\w*|without|nil)\b[^.\n]{0,24}$/i;

// What the OLD fence is made of, which is a different question from what the new one will be —
// timber fences are routinely replaced with Colorbond. Businesses price removal against
// core.removes (timber / metal / any), so only those two words are worth reading.
const REMOVES = [
  ['timber', /\b(?:timber|paling|wooden|hardwood|pine)\b[^.\n]{0,30}\bfenc/i],
  ['timber', /\bfenc\w*[^.\n]{0,30}\b(?:timber|paling|wooden)\b/i],
  ['metal', /\b(?:colou?rbond|steel|metal|alumin(?:i)?um|chain ?(?:mesh|wire|link)|wire)\b[^.\n]{0,30}\bfenc/i],
  ['metal', /\bfenc\w*[^.\n]{0,30}\b(?:colou?rbond|steel|metal|chain ?mesh)\b/i],
];

// Site conditions, in the schema's own vocabulary. This replaces the old easy/difficult access
// question outright: the business record prices sloped / rock / restricted_access / hand_dig
// separately, and has no way to charge for "difficult" as such.
const CONDITIONS = [
  ['sloped', /\bslop\w*|\bfall\b|steep|gradient|uneven ground/i],
  ['rock', /\brock\w*|\bshale\b|bluestone|basalt|hard ground/i],
  ['restricted_access', /\b(?:tight|difficult|restricted|limited|poor|narrow)\s+(?:site\s+|side\s+)?access\b|\baccess\b[^\n:]{0,20}[:\-–]\s*(?:is\s+)?(?:difficult|hard|tight|restricted|limited|poor)\b/i],
  ['hand_dig', /hand ?dig|hand ?excavat|no machine access|dig by hand/i],
];
// A document that states easy access has said something real: there is nothing tricky here.
const EASY_ACCESS = /\baccess\b[^\n:]{0,20}[:\-–]\s*(?:is\s+)?easy\b|\b(?:easy|clear|good|open|unrestricted)\s+(?:site\s+)?access\b|\bflat\s+and\s+clear\b/i;

// The job address, for the picker's benefit only. This is NOT checklist.suburb and never
// becomes it: ranking measures real distance, so it needs coordinates from Google, and a line
// of text can only ever be a head start. Labelled lines first — a contractor's letterhead is
// also an address, and quoting it would send the job to the wrong side of the city.
const ADDRESS = [
  /^[^\n]{0,40}\b(?:property|site|job|install(?:ation)?)\s*address\s*[:\-–]\s*([^\n]+)$/im,
  /^[^\n]{0,10}\baddress\s*[:\-–]\s*([^\n]+)$/im,
  /^[^\n]{0,40}\b(?:suburb|location)\s*[:\-–]\s*([^\n]+)$/im,
  // Unlabelled last resort: a place written the way Australian addresses are written.
  /\b([A-Z][A-Za-z'’\-]+(?:\s+[A-Z][A-Za-z'’\-]+){0,3}\s+(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT)\s+\d{4})\b/,
];

// The contractor's own address is on the page too, usually at the top, and suggesting it would
// send the job to whichever suburb the fencer trades from.
const LETTERHEAD = /\b(?:abn|acn|pty|ltd|p\/l|phone|mobile|email|www\.|@|fencing|fences|landscap|constructions?|quotation|invoice|tax invoice)\b/i;

const readAddress = (text) => {
  for (let index = 0; index < ADDRESS.length; index += 1) {
    const match = text.match(ADDRESS[index]);
    if (!match) continue;
    const line = String(match[1] || '').trim().replace(/\s+/g, ' ').slice(0, 120);
    // A label with nothing useful after it ("Address: TBC") is not a location. A street number
    // or a state code is what makes it something Google can actually find.
    if (!line || !/\d|\b(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT)\b/i.test(line)) continue;
    const unlabelled = index === ADDRESS.length - 1;
    if (unlabelled) {
      const lineStart = text.lastIndexOf('\n', match.index) + 1;
      let lineEnd = text.indexOf('\n', match.index);
      if (lineEnd === -1) lineEnd = text.length;
      if (LETTERHEAD.test(text.slice(lineStart, lineEnd))) continue;
    }
    return line;
  }
  return null;
};

const firstNumber = (text, patterns) => {
  for (const [pattern, refine] of patterns) {
    const match = text.match(pattern);
    if (!match) continue;
    const value = refine(Number(match[1]), match);
    if (Number.isFinite(value) && value > 0) return value;
  }
  return null;
};

const readDocument = (text) => {
  const facts = {};

  const material = MATERIALS.find(([, pattern]) => pattern.test(text));
  if (material) facts.material = material[0];

  const heightMm = firstNumber(text, HEIGHT);
  if (heightMm) facts.heightMm = heightMm;

  const lengthMeters = RANGE.some((pattern) => pattern.test(text)) ? null : asMetres(firstNumber(text, LENGTH));
  if (lengthMeters) facts.lengthMeters = lengthMeters;

  // A quote that never mentions an old fence has not said there isn't one, so silence stays
  // null and the customer gets asked. And a removal whose material the page never states is
  // still an unanswered question: businesses price timber and metal differently.
  const removing = REMOVAL.some((pattern) => {
    pattern.lastIndex = 0;
    return [...text.matchAll(pattern)].some(
      (match) => !NEGATED.test(text.slice(Math.max(0, match.index - 30), match.index)),
    );
  });
  if (removing) {
    const removes = REMOVES.find(([, pattern]) => pattern.test(text));
    if (removes) facts.removal = removes[0];
  }

  // Conditions are only ever read as a complete answer, never a partial one. A page that names
  // rock has not ruled out a slope, but it has told us the site is not "nothing tricky", and
  // half an answer here would silently drop a surcharge the business charges for.
  const conditions = CONDITIONS.filter(([, pattern]) => pattern.test(text)).map(([value]) => value);
  if (conditions.length) facts.conditions = conditions;
  else if (EASY_ACCESS.test(text)) facts.conditions = [];

  // The headline the customer means when they say what they were quoted: GST-inclusive, so the
  // largest of them, and never the Subtotal. The '$' is required — without it the "Total"
  // column heading swallows the first line item's quantity instead.
  const totals = [...text.matchAll(/(sub[\s-]*)?total\b[^\n$]{0,16}\$\s?([\d,]+(?:\.\d{1,2})?)/gi)]
    .filter((match) => !match[1])
    .map((match) => Number(match[2].replace(/,/g, '')))
    .filter((value) => Number.isFinite(value) && value > 0);
  if (totals.length) facts.existingPrice = Math.max(...totals);

  return facts;
};

// One document only. Across several, a height off one quote and a total off another describe a
// job nobody priced — the agent still reads those, with each one labelled.
const singleDocument = documents.length === 1 && !multipleDocuments;
const docFacts = singleDocument ? readDocument(extractedText) : {};

// Read on the same terms, and kept out of docFacts on purpose: everything in there is merged
// straight into the checklist downstream, and this must never land in checklist.suburb.
const docSuburbHint = singleDocument ? readAddress(extractedText) : null;

/* ------------------------------------------------------------------ the agent's briefing
   The model no longer picks the question or the options — that moved into code, because it is
   the model choosing its own next question that skipped fields, repeated them and invented
   choices nobody publishes. What it is still good at is reading a sentence, so it is given
   exactly what it needs to do that: what is already known, what was last asked, and which
   answers were on screen when the customer typed.                                          */
let known = {};
try { known = JSON.parse(source.knownChecklist || '{}') || {}; } catch (error) { known = {}; }
const ui = known._ui || {};

const sections = [];
if (extractedText) sections.push('--- Attached file/image content ---\n' + extractedText);
if (Object.keys(docFacts).length) {
  sections.push('--- Read off the attachment already, treat as settled ---\n' + JSON.stringify(docFacts));
}
if (docSuburbHint) {
  sections.push('--- Job address on the document (suggestedSuburb ONLY, never checklist.suburb) ---\n' + docSuburbHint);
}
const establishedKeys = Object.keys(known).filter((key) => key !== '_ui');
if (establishedKeys.length) {
  const established = {};
  for (const key of establishedKeys) established[key] = known[key];
  sections.push('--- Already established for this job ---\n' + JSON.stringify(established));
}
if (ui.lastAsked) {
  sections.push(
    '--- The question you asked last turn ---\nfield: ' + ui.lastAsked +
    '\nquestion: ' + (ui.lastQuestion || '') +
    '\nthe only values that were on screen: ' + JSON.stringify(ui.lastValues || []) +
    '\nThe customer is almost certainly answering THIS field.',
  );
}

const agentContext = [String(source.message || '')].concat(sections).join('\n\n');

return [{
  json: {
    message: source.message,
    sessionId: source.sessionId,
    extractedText,
    docFacts,
    docSuburbHint,
    agentContext,
    extractionFailed: false,
  },
}];

/* Everything the conversation knows, settled in one place, before anything is said back.
   The model used to decide what was answered, what was still missing and what to ask next, and
   that is where the three complaints came from: a field skipped, a field asked twice, and
   choices offered that no business publishes. So the decision moved here. The model still reads
   the customer's sentence — it is good at that — but every value it returns is validated
   against the schema before it is allowed in, and it may only fill the field it was actually
   asked about. Nothing it says can move the conversation somewhere it was not going. */
const source = $('Normalize Input').first().json;
const facts = $('Read Attachment Facts').first().json;
const parsed = ($input.first().json || {}).output || {};
const rawMessage = String(source.message || '');

const slug = (value) =>
  String(value == null ? '' : value).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const asObject = (value) => {
  if (value && typeof value === 'object') return value;
  try { return JSON.parse(value || 'null') || null; } catch (error) { return null; }
};

let place = asObject(source.place);
const known = asObject(source.knownChecklist) || {};

/* --------------------------------------------------------------- where the questions come from
   /schema/{trade}, fetched once by the router and passed down. Businesses publish rates against
   these exact slugs, so an option that is not in here matches nobody — which is why the lists
   are never written out in this file. The fallback exists only so a Firestore hiccup degrades to
   a working conversation instead of an empty one; it is a copy of the schema, not a second
   source of truth, and it will drift. */
let schema = {};
try { schema = JSON.parse(source.schemaJson || '{}') || {}; } catch (error) { schema = {}; }
const core = schema.core || {};
const labels = schema.labels || {};
const questions = schema.questions || {};
const extras = schema.extras || {};

const FALLBACK = {
  materials: ['timber_pine', 'timber_hardwood', 'colorbond', 'aluminium', 'pool_aluminium', 'pool_glass', 'chainmesh', 'rural_wire'],
  conditions: ['sloped', 'rock', 'restricted_access', 'hand_dig'],
  removes: ['timber', 'metal', 'any'],
  gateTypes: ['pedestrian_single', 'driveway_double', 'driveway_sliding', 'motor_automation'],
};
const listOf = (name) => {
  const value = core[name];
  return Array.isArray(value) && value.length ? value.slice() : FALLBACK[name].slice();
};

const materials = listOf('materials');
const conditionsList = listOf('conditions');
const gateTypes = listOf('gateTypes');
// 'any' is a business-side wildcard — "we'll take away whatever is there". A customer cannot
// answer it, so it never becomes a choice; the matching against it happens at pricing time.
const removes = listOf('removes').filter((value) => slug(value) !== 'any');

// Neither of these is in the schema: a length is a measurement, not a vocabulary, and the
// counts are just counts. Three at a time, same as everything else, so "Other" keeps working.
const LENGTHS = [10, 15, 20, 25, 30, 40, 50, 60, 80, 100];
const QUANTITIES = [1, 2, 3, 4, 5, 6];

const GROUPS = { material: 'materials', removal: 'removes', conditions: 'conditions', gateType: 'gateTypes' };
const titleCase = (value) => {
  const text = String(value).replace(/[_-]+/g, ' ').trim();
  return text ? text.charAt(0).toUpperCase() + text.slice(1) : '';
};
const labelFor = (field, value) => {
  const group = GROUPS[field];
  const table = group ? labels[group] || {} : {};
  if (table[value]) return String(table[value]);
  // An extra carries its own label — "Bamboo screening" — and is not in labels.materials.
  if (field === 'material' && extras[value] && extras[value].label) return String(extras[value].label);
  if (field === 'lengthMeters') return value + 'm';
  if (field === 'gateQty') return value + (Number(value) === 1 ? ' gate' : ' gates');
  if (field === 'heightKey') return String(value);
  return titleCase(value);
};

/* Heights are a schema list like everything else. They used to be read live from the rates of
   the businesses covering the customer, which meant a Firestore round-trip in the middle of the
   conversation just to draw one multiple choice. The brief is now built entirely from the
   schema, start to finish, and nothing is looked up until it is finished — so a height nobody
   can quote is caught at the end, where the answer is "here is what somebody CAN do" rather
   than a question that quietly disappears.
   core.heights may be a flat list, or a map keyed by material for trades where they differ. */
const HEIGHT_FALLBACK = ['1.2m', '1.5m', '1.8m', '2.1m', '0.9m', '1.35m', '2.4m'];
const heightsFromSchema = (material) => {
  const published = core.heights;
  if (Array.isArray(published) && published.length) return published.slice();
  if (published && typeof published === 'object') {
    const key = Object.keys(published).find((candidate) => slug(candidate) === slug(material));
    const list = key ? published[key] : null;
    if (Array.isArray(list) && list.length) return list.slice();
  }
  return HEIGHT_FALLBACK.slice();
};

const SOURCES = {
  material: materials,
  removal: removes,
  conditions: conditionsList,
  gateType: gateTypes,
  lengthMeters: LENGTHS,
  gateQty: QUANTITIES,
  heightKey: [],
};

/* Extras are the things one business offers that the trade vocabulary has no slug for —
   bamboo screening today, whatever the next one turns out to be. They are deliberately absent
   from SOURCES, so they never appear as a choice: most businesses cannot do them, and putting
   one in a three-option list would push out something everybody can. But a customer who names
   one by hand is naming something real — the business that offers it publishes its own price
   for it under capabilities.otherOfferings — so it is recognised here and priced later. */
const MATERIAL_CHOICES = materials.concat(Object.keys(extras));

/* ------------------------------------------------------------------------------ reading values
   Everything the model returns, everything the attachment gave up and everything the customer
   typed goes through here first. A value that is not one of the things a business can be paid
   for is not an answer, however confidently it was written. */
const oneOf = (field, value, listOverride) => {
  const list = listOverride || SOURCES[field] || [];
  const wanted = slug(value);
  if (!wanted) return null;
  const exact = list.find((entry) => slug(entry) === wanted);
  if (exact !== undefined) return exact;
  const byLabel = list.find((entry) => slug(labelFor(field, entry)) === wanted);
  if (byLabel !== undefined) return byLabel;
  // The customer typed words rather than a slug: "colorbond fence", "treated pine palings".
  const words = wanted.split('-').filter((word) => word.length > 2);
  if (!words.length) return null;
  const scored = list
    .map((entry) => {
      const entryWords = (slug(entry) + '-' + slug(labelFor(field, entry))).split('-').filter(Boolean);
      return { entry, hits: words.filter((word) => entryWords.includes(word)).length };
    })
    .filter((row) => row.hits > 0)
    .sort((a, b) => b.hits - a.hits);
  // Two equally good matches is not a match — "pool fence" means aluminium or glass, and
  // guessing one prices a job the customer never asked for.
  if (scored.length && (scored.length === 1 || scored[0].hits > scored[1].hits)) return scored[0].entry;

  // Typos. "colobond", "alumnium", "chainmesh" with a letter dropped — a trade word misspelled
  // by a character or two is still unmistakably that word, and re-asking the same question
  // because of one missing letter is the most irritating way this can fail. Short strings are
  // excluded: at four characters an edit of two is a different word entirely.
  if (wanted.length >= 5) {
    const editDistance = (a, b) => {
      if (Math.abs(a.length - b.length) > 3) return 99;
      let previous = Array.from({ length: b.length + 1 }, (unused, index) => index);
      for (let i = 1; i <= a.length; i += 1) {
        const current = [i];
        for (let j = 1; j <= b.length; j += 1) {
          current[j] = Math.min(
            previous[j] + 1,
            current[j - 1] + 1,
            previous[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1),
          );
        }
        previous = current;
      }
      return previous[b.length];
    };
    const limit = wanted.length >= 8 ? 2 : 1;
    const close = list
      .map((entry) => ({
        entry,
        distance: Math.min(editDistance(wanted, slug(entry)), editDistance(wanted, slug(labelFor(field, entry)))),
      }))
      .filter((row) => row.distance <= limit)
      .sort((a, b) => a.distance - b.distance);
    if (close.length && (close.length === 1 || close[0].distance < close[1].distance)) return close[0].entry;
  }
  return null;
};

const positiveNumber = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const text = String(value).replace(/,(?=\d{3}\b)/g, '');
  const match = text.match(/-?\d+(?:\.\d+)?/);
  if (!match) return null;
  const parsedNumber = Number(match[0]);
  return Number.isFinite(parsedNumber) && parsedNumber > 0 ? parsedNumber : null;
};

// Rates are keyed by height the way the business wrote it — "1.2m", "1.35m", "2.4m". Anything
// the customer, the model or a PDF offers is reduced to that one spelling, so "1800", "1800mm",
// "180cm" and "1.8 m" all end up as the same key and stop being four different misses.
const heightKeyFrom = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const text = String(value).trim().toLowerCase();
  const match = text.match(/(\d+(?:\.\d+)?)/);
  if (!match) return null;
  let metres = Number(match[1]);
  if (!Number.isFinite(metres) || metres <= 0) return null;
  if (/mm\b/.test(text) || metres > 300) metres /= 1000;
  else if (/cm\b/.test(text) || metres > 10) metres /= 100;
  if (metres <= 0 || metres > 10) return null;
  return String(Math.round(metres * 1000) / 1000) + 'm';
};

const NOTHING = /^\s*(none|no|nope|nil|n\/?a|nothing|nothing tricky|all good|its fine|it'?s fine|flat|easy|clear|standard)\b/i;
const conditionsFrom = (value) => {
  if (value === null || value === undefined) return null;
  if (Array.isArray(value) && value.length === 0) return [];
  const entries = Array.isArray(value) ? value : String(value).split(/[,;/&]|\band\b|\bplus\b/i);
  const found = [];
  let sawNothing = false;
  for (const entry of entries) {
    const text = String(entry == null ? '' : entry).trim();
    if (!text) continue;
    if (slug(text) === 'none' || NOTHING.test(text)) { sawNothing = true; continue; }
    const hit = oneOf('conditions', text);
    if (hit) found.push(hit);
  }
  if (found.length) return [...new Set(found)];
  return sawNothing ? [] : null;
};

const VALIDATE = {
  /* Never. The suburb is written from the confirmed place below and from nowhere else — not
     from the model, not from the attachment, and not from whatever the customer typed while
     the picker was on screen. Accepting the raw reply here put "what suburbs do you cover"
     into the brief as an address; it did not break the flow, because a suburb without
     coordinates still counts as missing, but it reached the recap and the brief panel. */
  suburb: () => null,
  material: (value) => oneOf('material', value, MATERIAL_CHOICES),
  heightKey: (value) => heightKeyFrom(value),
  lengthMeters: (value) => positiveNumber(value),
  removal: (value) => (slug(value) === 'none' || NOTHING.test(String(value || '')) ? 'none' : oneOf('removal', value)),
  conditions: (value) => conditionsFrom(value),
  gateType: (value) => (slug(value) === 'none' || NOTHING.test(String(value || '')) ? 'none' : oneOf('gateType', value)),
  gateQty: (value) => {
    const number = positiveNumber(value);
    return number === null ? null : Math.round(number);
  },
  existingPrice: (value) => positiveNumber(value),
};
const validate = (field, value) => {
  if (value === null || value === undefined) return null;
  const reader = VALIDATE[field];
  return reader ? reader(value) : null;
};

/* ------------------------------------------------------------------------------------- merging
   Order matters. What the client already had on screen is the baseline, because a turn that
   quietly drops an established value back to null is what produced "it asked me for the suburb
   again". The model may only touch the field it was actually asked about — or any field, once
   the customer has said something is wrong and we are in fixing mode. The attachment fills
   what is still empty and never overwrites an answer somebody gave out loud. */
const FIELDS = ['suburb', 'material', 'heightKey', 'lengthMeters', 'removal', 'conditions', 'gateType', 'gateQty'];
const ALL_FIELDS = FIELDS.concat(['existingPrice']);

const staticData = $getWorkflowStaticData('global');
if (!staticData.ui) staticData.ui = {};
const sessionId = source.sessionId || null;
// The client echoes the checklist back, _ui and all, so that is the primary copy. The mirror
// covers a client that strips keys it does not recognise.
const ui = known._ui || (sessionId ? staticData.ui[sessionId] : null) || {};

/* ------------------------------------------------------------------ a suburb nobody covers
   The client holds the place and sends it back every turn, so a suburb that no business reaches
   would arrive again on the next message, fail the same way, and produce the same reply for
   ever. Once a place has been told "nobody covers you", it is remembered and treated as no
   place at all — which puts the suburb question back on screen and gives the conversation
   somewhere to go instead of a wall.
   Picking one of the covered suburbs we offered is handled here too: the coordinates came back
   with the offer, so tapping one is a real place immediately, with no second trip to Google. */
const placeKey = (value) => {
  if (!value) return '';
  return slug(value.placeId || value.displayLabel || [value.suburb, value.postcode].filter(Boolean).join('-'));
};
const offeredPlaces = (ui.nearbyPlaces && typeof ui.nearbyPlaces === 'object') ? ui.nearbyPlaces : {};
const pickedNearby = offeredPlaces[slug(rawMessage)] || null;
const rejectedPlaces = Array.isArray(ui.rejectedPlaces) ? ui.rejectedPlaces : [];

if (pickedNearby) place = pickedNearby;
else if (place && rejectedPlaces.includes(placeKey(place))) place = null;

/* ------------------------------------------------------------- the address off the attachment
   The attachment is only present on the turn it was uploaded. Everything mined from it survives
   because it lands in the checklist and the client echoes that back — but the job address
   deliberately does NOT land in the checklist, because it is not an answer, only a head start
   for the picker. So on turn one it was read, and on turn two, which is when the suburb is
   actually asked, it was gone: the picker opened empty and the customer retyped an address they
   had already attached.
   It rides in _ui instead, alongside the other things the conversation has to remember, and is
   dropped the moment a real place comes back from the picker. */
const carriedSuburbHint = facts.docSuburbHint
  || (typeof parsed.suggestedSuburb === 'string' && parsed.suggestedSuburb.trim() ? parsed.suggestedSuburb.trim() : null)
  || (typeof ui.suburbHint === 'string' && ui.suburbHint.trim() ? ui.suburbHint.trim() : null)
  || null;

const docFacts = facts.docFacts || {};
const CHANGE_WORDS = /\b(actually|instead|change|changed|wrong|incorrect|not right|sorry|meant|rather|galat|badal|nahi)\b/i;
const fixing = ui.fixing === true || CHANGE_WORDS.test(rawMessage);
const mayOverwrite = (field) => field === ui.lastAsked || fixing;

/* A value the model produced for a field nobody asked about has to be visible in what the
   customer actually wrote, or in the document they attached. This is what stops a helpful
   sounding turn from quietly answering three questions the customer never saw — and it still
   lets "a 30m colorbond fence in Pakenham" fill three fields at once, because all three are
   right there in the sentence. A height nobody mentioned is dropped and asked instead. */
const haystack = rawMessage + ' ' + String(facts.extractedText || '');
const haystackSlug = slug(haystack);
const numbersIn = (haystack.match(/\d+(?:[.,]\d+)?/g) || [])
  .map((token) => Number(String(token).replace(/,/g, '')))
  .filter((value) => Number.isFinite(value));

const mentioned = (field, value) => {
  // The suburb is never taken from the model anyway — the picker decides it.
  if (field === 'suburb') return true;
  if (field === 'heightKey') return numbersIn.some((number) => heightKeyFrom(String(number)) === value);
  if (field === 'lengthMeters' || field === 'gateQty' || field === 'existingPrice') {
    return numbersIn.some((number) => Math.abs(number - Number(value)) < 0.01);
  }
  const values = Array.isArray(value) ? value : [value];
  // "Nothing tricky" is an empty array — there is no word to look for.
  if (!values.length) return true;
  return values.every((entry) => {
    const words = (slug(entry) + '-' + slug(labelFor(field, entry))).split('-').filter((word) => word.length > 2);
    return words.some((word) => haystackSlug.includes(word));
  });
};

const agentChecklist = (parsed && parsed.checklist) || {};
const merged = {};
for (const field of ALL_FIELDS) {
  const knownValue = validate(field, known[field]);
  const agentValue = validate(field, agentChecklist[field]);
  const docValue = validate(field, field === 'heightKey' ? (docFacts.heightKey || docFacts.heightMm) : docFacts[field]);

  let value = knownValue;
  if (value === null || mayOverwrite(field)) {
    const accept = agentValue !== null && (mayOverwrite(field) || mentioned(field, agentValue));
    value = accept ? agentValue : knownValue;
  }
  if (value === null) value = docValue;
  merged[field] = value;
}

// The customer tapped an option and the client sent its value straight through as the message.
// Resolved here rather than relying on the model to read its own multiple choice back — the
// choices were generated in code, so they can be recognised in code.
if (ui.lastAsked && ui.lastAsked !== 'alternative' && rawMessage) {
  const direct = validate(ui.lastAsked, rawMessage);
  if (direct !== null) merged[ui.lastAsked] = direct;
}

/* Nobody could quote the brief exactly, so the results turn offered the nearest things that
   somebody CAN do — "alt:colorbond:1.8m". Two fields move at once, which is why it carries its
   own prefix rather than looking like an answer to whichever question came last. */
let pickedAlternative = false;
if (ui.lastAsked === 'alternative' && /^alt:/i.test(rawMessage.trim())) {
  const [, altMaterial, altHeight] = rawMessage.trim().split(':');
  const material = validate('material', altMaterial);
  const heightKey = validate('heightKey', altHeight);
  if (material) { merged.material = material; pickedAlternative = true; }
  if (heightKey) merged.heightKey = heightKey;
}

// "No, the fence type is wrong" — the one thing that is allowed to empty a field, and only
// while the customer is actually correcting something.
const cleared = Array.isArray(parsed.clearFields) ? parsed.clearFields.map(slug) : [];
if (fixing && cleared.length) {
  for (const field of ALL_FIELDS) {
    if (cleared.includes(slug(field))) merged[field] = null;
  }
}

// Picker confirmation is the suburb, and nothing else ever is. A name off a document or a
// message is a head start for the picker, never an answer: ranking measures real distance, so
// it needs coordinates, and a name on its own can never produce a quote.
if (place) {
  merged.suburb = place.displayLabel
    || [place.suburb, place.state, place.postcode].filter(Boolean).join(', ')
    || merged.suburb;
}

// A 0 is the model filling in a default, never a quote anybody was given. Left as 0 it would
// hide every business, because nothing comes in under $0.
if (!(Number(merged.existingPrice) > 0)) merged.existingPrice = null;

const isMissing = (field) => {
  // A suburb nobody confirmed against Google is not established, whoever wrote it down.
  if (field === 'suburb') return !place;
  // Nothing to count when there is no gate.
  if (field === 'gateQty') return merged.gateType !== 'none' && (merged.gateQty === null || merged.gateQty === undefined);
  const value = merged[field];
  return value === null || value === undefined || value === '';
};

// The height list depends on the material, so it is only settled once that is answered.
if (merged.material) SOURCES.heightKey = heightsFromSchema(merged.material);

/* A height nobody builds at is not an answer, however clearly it was typed. Every other field
   is checked against the schema before it is allowed in; heights were not, because they were
   once read from live rates instead of a list. So "1.65m" went in, eight more questions were
   asked, and the search at the end found nothing — with no way for the customer to know which
   of their answers was the problem.
   It is not silently rounded either: 1.65m snapped to 1.8m is a different fence at a different
   price. The number is kept, the field is put back, and they are told what is actually built. */
let offListHeight = null;
if (merged.heightKey && SOURCES.heightKey.length) {
  const wanted = parseFloat(merged.heightKey);
  const onList = SOURCES.heightKey.find((entry) => Math.abs(parseFloat(entry) - wanted) < 0.001);
  if (onList === undefined) {
    offListHeight = merged.heightKey;
    merged.heightKey = null;
  } else {
    merged.heightKey = onList;
  }
}

const missing = FIELDS.filter(isMissing);
const nextField = missing.length ? missing[0] : null;

const turn = Number(ui.turn || 0) + 1;
const isFirstTurn = turn === 1;

/* Was the recap agreed to? The customer sees every answer read back before anything is looked
   up, and "no" has to be as easy as "yes" — so this is decided here, in code, on the raw reply,
   with the model's own read as a second opinion rather than the deciding one. */
const lastWasConfirmation = ui.lastType === 'confirmation';
const YES = /^\s*(y|ya|yes|yep|yeah|yup|correct|confirm(ed)?|all good|that'?s? (all )?(correct|right)|looks? (good|right)|sahi|theek|thik|ok(ay)?)\b/i;
const NO = /^\s*(n|no|nope|not quite|wrong|incorrect|nah|galat)\b/i;
const saidYes = lastWasConfirmation && (YES.test(rawMessage) || parsed.confirmed === true);
const saidNo = lastWasConfirmation && NO.test(rawMessage);

/* Nothing is looked up until the customer has said the brief is right. Every question and every
   choice comes from the schema, so the whole checklist is collected without touching a single
   business record; then it is read back for confirmation; and only a "yes" starts the search.
   Running it a turn early — on the recap itself — meant the customer could be told nobody
   covers them before they had agreed the details were even correct. */
const needsMatcher = !!place && nextField === null && (saidYes || pickedAlternative);

return [{
  json: {
    sessionId,
    trade: 'fencing',
    place,
    checklist: merged,
    missing,
    nextField,
    needsMatcher,
    turn,
    isFirstTurn,
    fixing,
    ui,
    sources: SOURCES,
    labels,
    questions,
    extras,
    schemaOk: Array.isArray(core.materials) && core.materials.length > 0,
    ack: typeof parsed.ack === 'string' ? parsed.ack.trim().slice(0, 40) : '',
    suggestedSuburb: typeof parsed.suggestedSuburb === 'string' && parsed.suggestedSuburb.trim()
      ? parsed.suggestedSuburb.trim() : null,
    wantsMoreOptions: parsed.wantsMoreOptions === true,
    confirmed: parsed.confirmed === true,
    docSuburbHint: facts.docSuburbHint || null,
    // What the picker should open with, whichever turn it was first seen on.
    suburbHint: carriedSuburbHint,
    // Carried so Format can keep remembering them, and so a place the customer just picked off
    // our own list is not thrown away on the next turn.
    rejectedPlaces,
    placeKey: placeKey(place),
    pickedAlternative,
    offListHeight,
    saidYes,
    saidNo,
    message: rawMessage,
  },
}];

/* The turn the customer actually sees. Every question and every choice on it is built here,
   from the schema and from what the covering businesses publish — never from the model. The
   model's only contribution is the two or three words of acknowledgement at the front.

   Three things this guarantees, which is the whole reason it exists:
     nothing is skipped   — the field asked is the first one still empty, in a fixed order;
     nothing is repeated  — a field with a value is never asked again;
     nothing is invented  — options come from schema slugs and real published rates. */
const state = $('Merge & Decide').first().json;

// The matcher only runs on the turns that need it, so this is genuinely absent most of the
// time. Referencing a node that did not execute throws, which is what the guard is for.
let matcher = null;
try { matcher = $('Call Shared Matcher').first().json || null; } catch (error) { matcher = null; }

const checklist = { ...(state.checklist || {}) };
const sessionId = state.sessionId || null;
const place = state.place || null;
const rawMessage = String(state.message || '');
const ui = state.ui || {};
const labels = state.labels || {};
const questions = state.questions || {};
const extras = state.extras || {};

const slug = (value) =>
  String(value == null ? '' : value).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const GROUPS = { material: 'materials', removal: 'removes', conditions: 'conditions', gateType: 'gateTypes' };
const titleCase = (value) => {
  const text = String(value).replace(/[_-]+/g, ' ').trim();
  return text ? text.charAt(0).toUpperCase() + text.slice(1) : '';
};
const labelFor = (field, value) => {
  const group = GROUPS[field];
  const table = group ? labels[group] || {} : {};
  if (table[value]) return String(table[value]);
  if (field === 'material' && extras[value] && extras[value].label) return String(extras[value].label);
  if (field === 'lengthMeters') return value + 'm';
  if (field === 'gateQty') return value + (Number(value) === 1 ? ' gate' : ' gates');
  if (field === 'heightKey') return String(value);
  return titleCase(value);
};

// Wording only — these are not business vocabulary, so they do not belong in the schema.
const DEFAULT_QUESTIONS = {
  suburb: 'Which suburb is the fence going in?',
  material: 'What type of fence are you after?',
  heightKey: 'What height are you after?',
  lengthMeters: 'How long is the fence?',
  removal: 'Is there an old fence that needs removing?',
  conditions: 'Anything tricky about the site?',
  gateType: 'Do you need any gates?',
  gateQty: 'How many of those gates?',
};
const questionFor = (field) => String(questions[field] || DEFAULT_QUESTIONS[field] || '').trim() || DEFAULT_QUESTIONS[field];

// The one choice on every question that is not a thing anybody sells. A business might publish
// four materials or fifty, so the list is never shown whole: three at a time, and "Other" is
// how the customer sees the rest — or types something that was never on the list at all.
const PAGE_SIZE = 3;
const PINNED = {
  removal: { label: 'Nothing to remove', value: 'none' },
  conditions: { label: 'Nothing tricky', value: 'none' },
  gateType: { label: 'No gates', value: 'none' },
};

/* The height list, like every other list, arrives from the schema already decided — see
   Merge & Decide. Nothing here talks to a business record: the whole brief is collected first,
   and only then is anything searched for. A single published height is not a question, though,
   so it is filled in rather than asked. */
const sources = { ...(state.sources || {}) };
let missing = Array.isArray(state.missing) ? state.missing.slice() : [];
let nextField = state.nextField;

if (nextField === 'heightKey' && (sources.heightKey || []).length === 1) {
  checklist.heightKey = sources.heightKey[0];
  missing = missing.filter((field) => field !== 'heightKey');
  nextField = missing.length ? missing[0] : null;
}

/* ------------------------------------------------------------------------------- pagination
   "Give me something else" advances one page. Running off the end is not an error — it wraps
   back to the start and says so, because a customer who has seen everything should be told
   that rather than handed the same three choices with no explanation. */
const WANTS_MORE = /\b(more|other|others|another|different|else|alternativ\w*|aur|koi\s+aur)\b/i;
const askingAgain = !!ui.lastAsked && state.nextField === ui.lastAsked;
const wantsMore = askingAgain && (state.wantsMoreOptions === true || WANTS_MORE.test(rawMessage));

const cursors = { ...(ui.cursor || {}) };
let exhausted = false;

const buildOptions = (field) => {
  const list = Array.isArray(sources[field]) ? sources[field] : [];
  const pinned = PINNED[field] || null;
  const slots = pinned ? PAGE_SIZE - 1 : PAGE_SIZE;

  let cursor = Number(cursors[field] || 0);
  if (!Number.isFinite(cursor) || cursor < 0) cursor = 0;
  if (wantsMore && field === state.nextField) {
    cursor += slots;
    if (cursor >= list.length) { cursor = 0; exhausted = true; }
  }
  if (cursor >= list.length) cursor = 0;
  cursors[field] = cursor;

  const options = list.slice(cursor, cursor + slots).map((value) => ({ label: labelFor(field, value), value }));
  if (pinned) options.push({ ...pinned });
  // Always last, always present. The client turns this one into a text box rather than sending
  // it back, so free text is how everything not on screen reaches us.
  options.push({ label: 'Other', value: '__other__' });
  return options;
};

const acknowledged = (text) => {
  const ack = String(state.ack || '').trim().replace(/[\s—–-]+$/, '');
  if (!ack || state.isFirstTurn) return text;
  return ack + ' — ' + text.charAt(0).toLowerCase() + text.slice(1);
};

/* ------------------------------------------------------------------------------ the decision */
let type = 'message';
let message = '';
let options = [];
let checklistComplete = false;
let fixing = false;
let noMatchReason = null;
// Set only on the turn where a suburb is handed back because nobody covered it.
let askingSuburbAgain = false;
let nearbyOffered = (ui.nearbyPlaces && typeof ui.nearbyPlaces === 'object') ? ui.nearbyPlaces : {};
let rejectedPlaces = Array.isArray(state.rejectedPlaces) ? state.rejectedPlaces.slice() : [];

/* The address the picker should open with — off the attachment, out of the customer's own
   sentence, or carried over from whichever earlier turn produced it. A suburb already ruled out
   is not a suggestion: offering it again is how the conversation looped the first time. */
const rejects = (value) => !!value && rejectedPlaces.some(
  (key) => key && (slug(value).includes(key) || key.includes(slug(value))));
let carriedHint = state.suburbHint || state.docSuburbHint || null;
if (rejects(carriedHint)) carriedHint = null;

const lastWasConfirmation = ui.lastType === 'confirmation';

// Decided in Merge & Decide, because the same answer also decides whether the search runs at
// all. Read here rather than worked out twice, so the two can never disagree.
const saidYes = state.saidYes === true;
const saidNo = state.saidNo === true;

if (matcher && matcher.matched !== true) {
  /* Nobody covers this customer. Saying so and stopping is what put the conversation in a loop:
     the client keeps the place and sends it back, so the next message failed the same way and
     got the same sentence, for ever. Two things fix it. The suburb that failed is remembered as
     rejected, so it stops counting as an answer and the question can be asked again. And rather
     than telling somebody to go and guess a nearby suburb, the ones this trade is actually
     worked out of are offered by name — the matcher already had to look at every service area
     to work out that none of them reached, so the list costs nothing extra, and the coordinates
     come with it so picking one needs no second trip to Google. */
  noMatchReason = matcher.noMatchReason || 'area';
  const here = slug(checklist.suburb || (place && place.suburb) || '');
  const suggestions = (Array.isArray(matcher.nearby) ? matcher.nearby : [])
    .filter((area) => area.suburb && slug(area.suburb) !== here && !slug(here).includes(slug(area.suburb)));

  const failed = checklist.suburb || (place && place.suburb) || 'that suburb';
  const preamble = noMatchReason === 'place'
    ? "I couldn't place that suburb on the map."
    : noMatchReason === 'radius'
      ? 'There are fencing businesses near ' + failed + ", but none of them travel far enough to reach you."
      : noMatchReason === 'pricing'
        ? 'There are fencing businesses around ' + failed + ", but none of them have confirmed their pricing yet."
        : 'No fencing business covers ' + failed + ' yet.';

  if (suggestions.length) {
    const shown = suggestions.slice(0, PAGE_SIZE);
    nearbyOffered = {};
    for (const area of shown) {
      const label = [area.suburb, area.state, area.postcode].filter(Boolean).join(', ');
      nearbyOffered[slug(area.suburb)] = {
        latitude: area.latitude,
        longitude: area.longitude,
        suburb: area.suburb,
        state: area.state,
        postcode: area.postcode,
        displayLabel: label,
      };
      // The value is the bare suburb, because that is also what the customer would type.
      options.push({ label: label + (area.distanceKm ? ' · ' + area.distanceKm + ' km' : ''), value: area.suburb });
    }
    options.push({ label: 'Somewhere else', value: '__other__' });
    message = preamble + ' These suburbs are covered — any of them work?';
    type = 'question';
  } else {
    message = preamble + ' Try a different suburb?';
    type = 'message';
    options = [];
  }
  // Do not let this suburb answer the question again on the next message.
  const failedKey = state.placeKey || slug(checklist.suburb || '');
  if (failedKey) rejectedPlaces = [...new Set(rejectedPlaces.concat(failedKey))].slice(-10);
  checklist.suburb = null;
  askingSuburbAgain = true;
} else if (state.isFirstTurn && missing.length > 0) {
  // Turn one is always the opener, whatever was mined off the attachment. It says outright that
  // what was provided is not enough — skipping straight to "happy to answer some questions?"
  // reads as though nobody looked at the file.
  const mined = ['material', 'heightKey', 'lengthMeters', 'removal', 'conditions']
    .filter((field) => checklist[field] !== null && checklist[field] !== undefined);
  message = mined.length
    ? "Got the details off that, but it's not quite enough to match you properly yet. Mind if I ask a few quick questions?"
    : 'Happy to help with that. Mind if I ask a few quick questions?';
  type = 'message';
  options = [];
} else if ((saidYes || state.pickedAlternative === true) && missing.length === 0) {
  message = acknowledged('Let me check what businesses are available near you…');
  type = 'message';
  options = [];
  checklistComplete = true;
} else if (saidNo) {
  message = "No worries — what should I fix?";
  type = 'message';
  options = [];
  fixing = true;
} else if (nextField) {
  const question = questionFor(nextField);

  if (nextField === 'suburb') {
    // The only field the client collects with something other than a tap: a mistyped suburb
    // does not fail loudly, it silently matches zero businesses, so the client swaps its reply
    // box for a Google-backed picker and sends back a real place.
    //
    const hint = carriedHint;

    // If we already told them which suburbs are covered and they typed something else instead
    // of tapping one, the picker is the right answer — Google can resolve anything they type —
    // but the covered ones are still worth repeating, so the list is not simply lost.
    const covered = Object.keys(nearbyOffered)
      .map((key) => nearbyOffered[key] && nearbyOffered[key].suburb)
      .filter(Boolean)
      .slice(0, 3);

    message = hint
      ? 'I found ' + hint + ' — confirm that suburb from the list?'
      : covered.length
        ? question + ' ' + covered.join(', ') + (covered.length > 1 ? ' are covered.' : ' is covered.')
        : question;
    type = 'message';
    options = [];
  } else {
    options = buildOptions(nextField);
    // The same question coming back with no explanation is what makes this feel like a loop.
    // If we asked this field last turn and the customer's reply did not resolve to anything —
    // a typo the fuzzy match could not reach, or a sentence about something else — say so once
    // rather than repeating the question as though they had said nothing at all.
    const misunderstood = askingAgain && !wantsMore && !exhausted && rawMessage.trim().length > 0
      && !state.offListHeight;
    // Running off the end of the list is worth saying out loud. It replaces the
    // acknowledgement rather than stacking on top of it — two dashes in one sentence reads
    // like a fault.
    // A height that is not built at all needs naming, or the same list comes back looking like
    // the question was simply ignored.
    const offList = nextField === 'heightKey' && state.offListHeight
      ? 'Fences are not built at ' + state.offListHeight + ' — '
      : null;

    message = offList
      ? offList + 'which of these is closest?'
      : exhausted
        ? "That's everything we cover — " + question.charAt(0).toLowerCase() + question.slice(1)
        : misunderstood
          ? "Sorry, I didn't catch that — " + question.charAt(0).toLowerCase() + question.slice(1)
          : acknowledged(question);
    type = 'question';
  }
} else if (!lastWasConfirmation) {
  // Everything is known. One recap, then the handoff — and the recap is built from the values
  // in the checklist, never from a sentence the model wrote, so it can never mention a value
  // that is not actually stored.
  const recap = [
    checklist.suburb,
    labelFor('material', checklist.material),
    checklist.heightKey,
    checklist.lengthMeters ? checklist.lengthMeters + 'm' : null,
    checklist.removal && checklist.removal !== 'none' ? 'removing the old ' + labelFor('removal', checklist.removal).toLowerCase() : null,
    Array.isArray(checklist.conditions) && checklist.conditions.length
      ? checklist.conditions.map((value) => labelFor('conditions', value).toLowerCase()).join(', ')
      : null,
    checklist.gateType && checklist.gateType !== 'none'
      ? (checklist.gateQty || 1) + ' x ' + labelFor('gateType', checklist.gateType).toLowerCase()
      : null,
  ].filter(Boolean).join(', ');
  message = 'Got it — ' + recap + '. All correct?';
  type = 'confirmation';
  options = [
    { label: "Yes, that's all correct", value: 'yes' },
    { label: "No, something's wrong", value: 'no' },
  ];
} else {
  // A confirmation was on screen and the reply was neither yes nor no. Ask it again rather than
  // guessing which way they meant it.
  message = 'Sorry — is that all correct?';
  type = 'confirmation';
  options = [
    { label: "Yes, that's all correct", value: 'yes' },
    { label: "No, something's wrong", value: 'no' },
  ];
}

// None of this is an answer — the customer still taps the Google suggestion, which is the only
// thing that produces coordinates. Re-checked against the rejects because the branch above may
// have just added one.
const suburbHint = rejects(carriedHint) ? null : carriedHint;
// The picker opens when we are asking for a suburb and have no list of covered ones to tap.
// "Somewhere else" on the covered-suburbs list lands here on the following turn.
const expectsSuburb = options.length === 0
  && (askingSuburbAgain || (!place && /\bsuburbs?\b|\bpost ?code\b|\bsuggestions\b/i.test(message)));

const uiOut = {
  turn: state.turn,
  cursor: cursors,
  lastAsked: askingSuburbAgain
    ? 'suburb'
    : (type === 'question' || expectsSuburb ? (missing[0] || nextField || null) : null),
  lastQuestion: message,
  lastValues: options.map((option) => option.value),
  lastType: type,
  fixing,
  // The suburbs already ruled out, and the covered ones currently on screen with the
  // coordinates that came back with them.
  rejectedPlaces,
  nearbyPlaces: nearbyOffered,
  // Carried until the picker returns a real place; after that there is nothing left to prefill.
  suburbHint: place ? null : suburbHint,
};

// Mirrors the round-tripped copy, for a client that strips keys it does not recognise. Bounded,
// because a workflow's static data is forever otherwise.
const staticData = $getWorkflowStaticData('global');
if (!staticData.ui) staticData.ui = {};
if (sessionId) {
  staticData.ui[sessionId] = uiOut;
  const keys = Object.keys(staticData.ui);
  if (keys.length > 500) {
    for (const key of keys.slice(0, keys.length - 400)) delete staticData.ui[key];
  }
}

// The same values the customer would recognise, for whatever the client shows alongside the
// chat. checklist itself holds slugs, because that is what businesses publish rates against —
// and a brief panel reading "Material: timber_pine" is the slug leaking through to somebody who
// never needed to see it.
const FIELD_TITLES = {
  suburb: 'Suburb', material: 'Material', heightKey: 'Height', lengthMeters: 'Length',
  removal: 'Old fence', conditions: 'Site conditions', gateType: 'Gate', gateQty: 'Gates',
};
const checklistDisplay = {};
for (const field of Object.keys(FIELD_TITLES)) {
  const value = checklist[field];
  if (value === null || value === undefined || value === '') continue;
  let text;
  if (field === 'suburb' || field === 'heightKey') text = String(value);
  else if (field === 'conditions') {
    text = Array.isArray(value) && value.length
      ? value.map((entry) => labelFor('conditions', entry)).join(', ')
      : 'Nothing tricky';
  } else if (field === 'removal') text = value === 'none' ? 'Nothing to remove' : labelFor('removal', value);
  else if (field === 'gateType') text = value === 'none' ? 'No gates' : labelFor('gateType', value);
  else text = labelFor(field, value);
  checklistDisplay[field] = { title: FIELD_TITLES[field], value: text };
}

return [{
  json: {
    sessionId,
    trade: 'fencing',
    // Derived from the brief, not from a classifier that could flip mid-conversation: a quote
    // the customer already holds turns the results page into a comparison.
    intent: Number(checklist.existingPrice) > 0 ? 'compare_quote' : 'new_quote',
    place,
    type,
    message,
    options,
    ...(expectsSuburb ? { expects: 'suburb' } : {}),
    ...(expectsSuburb && suburbHint ? { suggestedSuburb: suburbHint } : {}),
    ...(noMatchReason ? { noMatchReason } : {}),
    checklistComplete,
    checklist: { ...checklist, _ui: uiOut },
    checklistDisplay,
    // Read by the results turn, which has to name a material the customer never picked.
    labels,
    results: [],
    avgRatePerMeter: null,
  },
}];

/* Every business that covers the customer, priced off its own published rates, cheapest first.
   Finding them happens in the shared matcher — identical for every trade — so they arrive here
   already filtered, each paired with the document it published for fencing.

   This runs once, at the end, against a finished brief. Nothing above this node has touched a
   business record: the whole checklist is collected from /schema/fencing first, so the customer
   answers a straight run of questions and the search happens when there is a complete job to
   search with.

   When nothing can quote the brief exactly, that is not the end of it. The businesses covering
   this customer can quote SOMETHING, and the nearest of those is worth putting on screen —
   "no treated pine at 1.8m near you, but Colorbond at 1.8m is $2,750" is an answer; "nobody
   does that" is a dead end with the same data behind it. */
const gate = $('Format Fencing Result').first().json;
const checklist = gate.checklist || {};
const sessionId = gate.sessionId || null;
const intent = gate.intent;
const labels = gate.labels || {};

// The matcher ran on this same turn — Format only lets a finished brief through — but the
// reference is guarded anyway: a throw here would reach the customer as a dead webhook.
let matcher = {};
try { matcher = $('Call Shared Matcher').first().json || {}; } catch (error) { matcher = {}; }

const slug = (value) =>
  String(value == null ? '' : value).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const titleCase = (value) => {
  const text = String(value).replace(/[_-]+/g, ' ').trim();
  return text ? text.charAt(0).toUpperCase() + text.slice(1) : '';
};
/* slug() turns pool_glass into pool-glass, which is right for comparing and wrong for anything
   the customer reads or sends back. The schema's own spelling is the canonical one, so a value
   is put back into it before it is labelled or offered — labels.materials is keyed that way,
   and so is everything the fencing workflow validates against. */
const canonicalMaterial = (value) => {
  const keys = Object.keys(labels.materials || {});
  const hit = keys.find((key) => slug(key) === slug(value));
  return hit || String(value);
};
const materialLabel = (value) => {
  const key = canonicalMaterial(value);
  return (labels.materials || {})[key] ? String(labels.materials[key]) : titleCase(key);
};

const fail = (message, reason, extra) => [{
  json: {
    sessionId, trade: 'fencing', intent, type: 'result', message, options: [], results: [],
    avgRatePerMeter: null, comparison: null, noMatchReason: reason,
    checklist, checklistComplete: true, ...(extra || {}),
  },
}];

// n8n does not always throw when a sub-workflow fails — an empty item comes back instead. Left
// unchecked that reads to the customer as "nobody covers you", which is a different and much
// more damaging statement than "something broke".
if (matcher.matched === undefined) {
  return fail('Something went wrong finding businesses near you — mind trying again in a moment?', 'error');
}

// Format handles a no-coverage result before this node ever runs, so reaching here means the
// matcher found businesses. Kept as a guard rather than an assumption.
if (matcher.matched !== true) {
  return fail('No fencing business covers that suburb yet. Try a nearby suburb?', matcher.noMatchReason || 'area');
}

const num = (value) => {
  const raw = value !== null && typeof value === 'object'
    ? (value.doubleValue ?? value.integerValue ?? value.stringValue ?? null)
    : value;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
};

// Every figure the customer sees, and every figure compared against theirs, is what they would
// actually pay. Some businesses publish GST-inclusive rates and some do not, and the customer's
// own quote almost always includes it — so an exclusive rate looks 10% cheaper than it is.
const GST_MULTIPLIER = 1.1;
const payable = (amount, gstIncluded) => (gstIncluded ? Math.round(amount) : Math.round(amount * GST_MULTIPLIER));

const wantedMaterial = slug(checklist.material);
const wantedHeight = parseFloat(String(checklist.heightKey || ''));
const lengthMetres = num(checklist.lengthMeters) || 0;
const wantedConditions = Array.isArray(checklist.conditions) ? checklist.conditions : [];
const removalWanted = checklist.removal && checklist.removal !== 'none' ? slug(checklist.removal) : null;
const gateWanted = checklist.gateType && checklist.gateType !== 'none' ? slug(checklist.gateType) : null;
const gateQty = Math.max(1, Math.round(num(checklist.gateQty) || 1));

const businesses = Array.isArray(matcher.businesses) ? matcher.businesses : [];
const documents = Array.isArray(matcher.pricing) ? matcher.pricing : [];

/* One business, one fence. Everything except the material and the height is the customer's
   brief unchanged, which is what makes an alternative an alternative rather than a different
   job: the length, the removal, the site conditions and the gate all still apply. Returns a
   priced quote, or the wall this business hit, so the failure can be explained. */
const quoteFor = (business, document, materialSlug, heightMetres, heightLabel) => {
  const pricing = document.pricing || {};
  const capabilities = document.capabilities || {};
  const enabled = Array.isArray(pricing.enabledMaterials) ? pricing.enabledMaterials.map(slug) : [];

  let rate = null;
  let priced = heightLabel;

  if (enabled.includes(materialSlug)) {
    // rates is keyed by the business's own spelling of the material, so find the key that means
    // the same thing rather than assuming ours matches theirs.
    const rates = pricing.rates || {};
    const rateKey = Object.keys(rates).find((key) => slug(key) === materialSlug);
    if (!rateKey) return { blocked: 'material' };

    // Heights are written "1.2m", "1.35m", "2.4m" and compared as numbers, so "1.8m" and
    // "1.80m" are the same height rather than two different misses.
    const table = rates[rateKey] || {};
    const key = Object.keys(table).find((entry) => Math.abs(parseFloat(entry) - heightMetres) < 0.001);
    if (key === undefined) return { blocked: 'height' };
    rate = num(table[key]);
    priced = key;
    // A business that publishes no rate at this height cannot quote it. Dropping it is right;
    // inventing a number from a neighbouring height would not be their price.
    if (rate === null) return { blocked: 'height' };
  } else {
    // Something outside the trade vocabulary that this business does anyway, priced on its own
    // line rather than in the rate table. It carries a single per-metre price, and at most one
    // height — the only height that business builds it at.
    const offerings = Array.isArray(capabilities.otherOfferings) ? capabilities.otherOfferings : [];
    const offering = offerings.find((row) => slug(row.slug) === materialSlug || slug(row.label) === materialSlug);
    if (!offering) return { blocked: 'material' };
    const offeredHeight = num(offering.heightM);
    if (offeredHeight !== null && Number.isFinite(heightMetres) && Math.abs(offeredHeight - heightMetres) > 0.001) {
      return { blocked: 'height' };
    }
    rate = num(offering.pricePerMetre);
    if (rate === null) return { blocked: 'material' };
  }

  // Removal is priced by what the OLD fence is made of, which is routinely not what the new one
  // will be. 'any' is the wildcard a business sets when it will take away whatever is there.
  let removalPerMetre = 0;
  if (removalWanted) {
    const removals = Array.isArray(pricing.removals) ? pricing.removals : [];
    const entry = removals.find((row) => slug(row.removes) === removalWanted)
      || removals.find((row) => slug(row.removes) === 'any');
    // They cannot take the old fence away, so they cannot do this job. Quoting them without the
    // removal would show a price for work the customer did not ask for.
    if (!entry) return { blocked: 'removal' };
    removalPerMetre = num(entry.pricePerMetre) || 0;
  }

  // Named surcharges, not a difficulty flag. A business that never listed a condition simply
  // does not charge extra for it — that is not a reason to drop them.
  let conditionPerMetre = 0;
  let conditionPercent = 0;
  const published = Array.isArray(pricing.siteConditions) ? pricing.siteConditions : [];
  for (const wanted of wantedConditions) {
    const entry = published.find((row) => slug(row.condition) === slug(wanted));
    if (!entry) continue;
    conditionPerMetre += num(entry.extraPerMetre) || 0;
    conditionPercent += num(entry.extraPercent) || 0;
  }

  let gatesTotal = 0;
  let gateFromPrice = false;
  if (gateWanted) {
    const gates = Array.isArray(pricing.gates) ? pricing.gates : [];
    // A gate priced against a specific material wins over one priced for anything.
    const entry = gates.find((row) => slug(row.gateType) === gateWanted && slug(row.material) === materialSlug)
      || gates.find((row) => slug(row.gateType) === gateWanted && !row.material);
    if (!entry) return { blocked: 'gate' };
    gatesTotal = (num(entry.price) || 0) * gateQty;
    gateFromPrice = entry.isFromPrice === true;
  }

  const gstIncluded = pricing.gstIncluded === true;
  // The percentage surcharge is a loading on the work done along the fence line, so it applies
  // to the install and the removal and not to a gate, which is a fixed item either way.
  const perMetre = (rate + removalPerMetre + conditionPerMetre) * (1 + conditionPercent / 100);
  const subtotal = perMetre * lengthMetres + gatesTotal;
  // The floor is a real price too, so it is put on the same basis as the rest.
  const minimumCharge = payable(num(pricing.minimumCharge) || 0, gstIncluded);
  const total = Math.max(payable(subtotal, gstIncluded), minimumCharge);

  const badges = [];
  // GST is per business and some publish inclusive, some not — the label goes on every card so
  // a cheaper-looking number is never just a missing 10%.
  badges.push(gstIncluded ? 'incl. GST' : 'incl. GST (added)');
  badges.push(business.distanceKm > 0 ? business.distanceKm + ' km away' : 'In your suburb');
  if (business.rating) badges.push(business.reviewCount ? business.rating + '★ (' + business.reviewCount + ')' : business.rating + '★');
  if (removalPerMetre > 0) badges.push('Removal included');
  if (conditionPerMetre > 0 || conditionPercent > 0) badges.push('Site conditions included');
  if (gatesTotal > 0) badges.push(gateQty === 1 ? 'Gate included' : gateQty + ' gates included');
  if (gateFromPrice) badges.push('Gate priced from');
  // Permits are the commonest surprise on a fencing invoice, and this document states outright
  // whether they were priced in.
  if (capabilities.permits && capabilities.permits.included === false) badges.push('Permits not included');
  if (business.isAutoAcceptEnabled) badges.push('Instant accept');

  return {
    uid: business.uid,
    businessName: business.businessName,
    suburb: business.suburb,
    distanceKm: business.distanceKm,
    material: materialSlug,
    heightKey: priced,
    ratePerMeter: payable(perMetre, gstIncluded),
    // Travels to the client so the saved job can go straight into this business's
    // accepted_jobs instead of waiting in incoming_jobs.
    autoAcceptsAi: business.autoAcceptsAi === true,
    currency: pricing.currency || 'AUD',
    projectTotalMin: total,
    projectTotalMax: total,
    estimatedTotal: total,
    warranty: (capabilities.warranty && capabilities.warranty.text) || null,
    badges,
  };
};

const quotes = [];
const blocked = { material: 0, height: 0, removal: 0, gate: 0 };

for (let index = 0; index < documents.length; index += 1) {
  const business = businesses[index] || {};
  const document = documents[index] || {};
  if (!business.uid) continue;
  const quote = quoteFor(business, document, wantedMaterial, wantedHeight, checklist.heightKey);
  if (quote.blocked) { blocked[quote.blocked] += 1; continue; }
  quotes.push(quote);
}

quotes.sort((a, b) => a.projectTotalMin - b.projectTotalMin || b.ratePerMeter - a.ratePerMeter);

const rawPrice = num(checklist.existingPrice);
const existingPrice = rawPrice !== null && rawPrice > 0 ? rawPrice : null;
// What businesses round here charge for this job — every one that could quote it, not just the
// handful shown. Averaging only the cheapest three would flatter the result.
const average = quotes.length > 0
  ? Math.round(quotes.reduce((sum, quote) => sum + quote.projectTotalMin, 0) / quotes.length)
  : null;

// "Beat this price" has one honest answer: only what actually beats it. Showing something
// dearer would turn the whole feature into its opposite.
const beating = existingPrice === null ? quotes : quotes.filter((quote) => quote.projectTotalMin < existingPrice);
const top = beating.slice(0, 3);

if (top.length === 0 && existingPrice !== null && quotes.length > 0) {
  const closest = quotes[0].projectTotalMin;
  return fail('Nobody covering your suburb came in under $' + existingPrice.toLocaleString() +
    '. The closest was $' + closest.toLocaleString() + ', so the quote you have is already a good one.', 'notCheaper');
}

/* ------------------------------------------------------------------------ the nearest thing
   Nothing could quote the brief as written. Everything else about the job still stands, so the
   same businesses are asked again for every material and height they DO publish — the length,
   the removal, the site conditions and the gate all unchanged. What comes back is a real price
   from a real business for a job one detail away from the one they asked for, which is a far
   better answer than the wall. Closest first: same material at a different height beats a
   different material, and after that it is cheapest. */
if (top.length === 0) {
  const alternatives = [];
  for (let index = 0; index < documents.length; index += 1) {
    const business = businesses[index] || {};
    const document = documents[index] || {};
    if (!business.uid) continue;
    const pricing = document.pricing || {};
    const enabled = Array.isArray(pricing.enabledMaterials) ? pricing.enabledMaterials.map(slug) : [];
    const rates = pricing.rates || {};
    for (const rateKey of Object.keys(rates)) {
      const material = slug(rateKey);
      if (!enabled.includes(material)) continue;
      for (const heightKey of Object.keys(rates[rateKey] || {})) {
        const metres = parseFloat(heightKey);
        if (!Number.isFinite(metres) || metres <= 0) continue;
        if (material === wantedMaterial && Math.abs(metres - wantedHeight) < 0.001) continue;
        const quote = quoteFor(business, document, material, metres, heightKey);
        if (quote.blocked) continue;
        if (existingPrice !== null && quote.projectTotalMin >= existingPrice) continue;
        alternatives.push({
          ...quote,
          // The business's own spelling of the material, mapped back to the schema's, so the
          // option value the customer taps is one the checklist can accept as-is.
          material: canonicalMaterial(rateKey),
          // Same material, different height is one change. A different material is two.
          distanceFromBrief: (material === wantedMaterial ? 0 : 2)
            + (Math.abs(metres - wantedHeight) < 0.001 ? 0 : 1),
        });
      }
    }
  }

  alternatives.sort((a, b) =>
    a.distanceFromBrief - b.distanceFromBrief || a.projectTotalMin - b.projectTotalMin);

  // One line per material-and-height, cheapest business for it.
  const seen = new Set();
  const offers = [];
  for (const alternative of alternatives) {
    const key = alternative.material + '|' + alternative.heightKey;
    if (seen.has(key)) continue;
    seen.add(key);
    offers.push(alternative);
    if (offers.length >= 3) break;
  }

  if (offers.length) {
    const asked = materialLabel(checklist.material) + (checklist.heightKey && checklist.heightKey !== 'any'
      ? ' at ' + checklist.heightKey : '');
    const uiOut = {
      ...((checklist._ui && typeof checklist._ui === 'object') ? checklist._ui : {}),
      lastAsked: 'alternative',
      lastType: 'question',
      lastQuestion: 'alternatives',
      lastValues: offers.map((offer) => 'alt:' + offer.material + ':' + offer.heightKey),
    };
    return [{
      json: {
        sessionId, trade: 'fencing', intent,
        type: 'question',
        message: 'Nobody near you does ' + asked + '. The closest they can do is '
          + materialLabel(offers[0].material) + ' at ' + offers[0].heightKey
          + ', $' + offers[0].projectTotalMin.toLocaleString() + ' from ' + offers[0].businessName
          + '. Want one of these instead?',
        options: offers.map((offer) => ({
          label: materialLabel(offer.material) + ', ' + offer.heightKey
            + ' · $' + offer.projectTotalMin.toLocaleString(),
          value: 'alt:' + offer.material + ':' + offer.heightKey,
        })).concat([{ label: "No thanks, I'll change something", value: 'no' }]),
        noMatchReason: 'alternative',
        // The brief is not finished after all — one of its answers has to move.
        checklistComplete: false,
        checklist: { ...checklist, _ui: uiOut },
        results: [],
        avgRatePerMeter: null,
        // The full set, in case the client would rather render its own comparison.
        alternatives: offers.map((offer) => ({
          material: offer.material,
          materialLabel: materialLabel(offer.material),
          heightKey: offer.heightKey,
          businessId: offer.uid,
          businessName: offer.businessName,
          estimatedTotal: offer.projectTotalMin,
          value: 'alt:' + offer.material + ':' + offer.heightKey,
        })),
      },
    }];
  }

  // Not one business could quote anything at all for this job. Say which wall they hit — a
  // material nobody nearby offers is a different problem from a removal nobody does.
  const reason = blocked.removal > 0 ? 'removal'
    : blocked.gate > 0 ? 'gate'
      : blocked.height > 0 ? 'height'
        : blocked.material > 0 ? 'material' : 'pricing';
  const message = reason === 'removal'
    ? "None of the businesses near you take away that kind of old fence. Want to arrange the removal separately?"
    : reason === 'gate'
      ? 'Nobody near you prices that gate. Want to try without the gate?'
      : reason === 'height'
        ? 'Nobody near you publishes a rate at that height. Want to try a different height?'
        : reason === 'material'
          ? 'The businesses near you do not offer that fence type yet. Want to try a different type?'
          : 'I found businesses near you, but none of them have finished setting up their pricing yet.';
  return fail(message, reason);
}

const benchmark = existingPrice === null ? average : existingPrice;
const cheapest = top[0].projectTotalMin;

return [{
  json: {
    sessionId,
    trade: 'fencing',
    intent,
    type: 'result',
    message: 'Here are the local businesses that cover your job.',
    options: [],
    // The client's existing shape, so the results page needs no change to render these.
    results: top.map((quote) => ({
      businessId: quote.uid,
      autoAcceptsAi: quote.autoAcceptsAi,
      businessName: quote.businessName,
      suburb: quote.suburb,
      ratePerMeter: quote.ratePerMeter,
      estimatedTotal: quote.estimatedTotal,
      notes: quote.badges.join(' · '),
    })),
    avgRatePerMeter: Math.round(top.reduce((sum, quote) => sum + quote.ratePerMeter, 0) / top.length),
    comparison: {
      potentialSavings: benchmark > cheapest ? benchmark - cheapest : null,
      marketAverage: average,
      // Every business that covers them, including the ones that could not quote this job or
      // came in above their price — that is what "screened" honestly means.
      totalQuotesScreened: matcher.totalCovering || businesses.length,
      userExistingPrice: existingPrice,
      quotes: top.map((quote) => ({
        businessId: quote.uid,
        autoAcceptsAi: quote.autoAcceptsAi,
        businessName: quote.businessName,
        ratePerMeter: quote.ratePerMeter,
        projectTotalMin: quote.projectTotalMin,
        projectTotalMax: quote.projectTotalMax,
        badges: quote.badges,
        warranty: quote.warranty,
        tag: quote.projectTotalMin === cheapest ? 'BEST_VALUE' : null,
        savingsFromAverage: benchmark > quote.projectTotalMin ? benchmark - quote.projectTotalMin : null,
        suburb: quote.suburb,
      })),
    },
    checklist,
    checklistComplete: true,
  },
}];
